#!/usr/bin/env node
// lhc_bundle.js — single-file bundler for the scscm compiler (lhc.js)
//
// Produces dist/lhc.js: a self-contained Node.js script that contains the
// scscm compiler and all of its dependencies inlined. The output runs with
// only a stock Node.js installation — no adjacent files, no `npm install`.
//
// Usage:
//   node cli/lhc_bundle.js                       # writes dist/lhc.js
//   node cli/lhc_bundle.js --out-dir other/      # writes other/lhc.js

'use strict';

const fs   = require('node:fs');
const path = require('node:path');

const CLI_DIR   = path.resolve(__dirname);
const REPO_ROOT = path.resolve(CLI_DIR, '..');

// ── CLI args ──────────────────────────────────────────────────────────────────

const args = process.argv.slice(2);
const outDir = (() => {
  const i = args.indexOf('--out-dir');
  return i !== -1 ? path.resolve(args[i + 1]) : path.join(REPO_ROOT, 'dist');
})();

// ── Discover version (baked into bundle) ─────────────────────────────────────

const PKG_VERSION = (() => {
  try {
    const pkg = JSON.parse(fs.readFileSync(path.join(CLI_DIR, 'package.json'), 'utf8'));
    return pkg.version || 'unknown';
  } catch (_) {
    return 'unknown';
  }
})();

// ── Module set to embed ───────────────────────────────────────────────────────
// Order does not matter for definition; the entry module pulls them in lazily.

const MODULES = [
  './hc_utils.js',
  './lhc_lexer.js',
  './lhc_parser.js',
  './lhc_macros.js',
  './lhc_codegen.js',
];

const ENTRY = './lhc.js';

// ── Source transforms ─────────────────────────────────────────────────────────

function readModule(rel) {
  let src = fs.readFileSync(path.join(CLI_DIR, rel), 'utf8');
  // Strip shebang — only valid as the first line of a file, not mid-bundle.
  if (src.startsWith('#!')) src = src.replace(/^#![^\n]*\n/, '');
  return src;
}

// hc_utils.getVersion() reads cli/package.json via __dirname. In a bundle
// __dirname is wrong, so we replace the function body with a baked literal.
function patchHcUtils(source) {
  const re = /function getVersion\(\) \{[\s\S]*?\n\}/;
  const baked = `function getVersion() { return ${JSON.stringify(PKG_VERSION)}; }`;
  if (!re.test(source)) {
    throw new Error('lhc_bundle: could not locate getVersion() in hc_utils.js — patch needs updating');
  }
  return source.replace(re, baked);
}

// lhc.js wraps main() in `if (require.main === module) { ... }`. In a bundle
// we want main() to run unconditionally at end-of-file, so strip the guard.
function patchEntry(source) {
  const re = /if \(require\.main === module\) \{\s*main\(\)\.catch\([\s\S]*?\}\);\s*\}/;
  if (!re.test(source)) {
    throw new Error('lhc_bundle: could not locate require.main guard in lhc.js — patch needs updating');
  }
  return source.replace(re, '/* require.main guard stripped by lhc_bundle */');
}

// ── Emitters ──────────────────────────────────────────────────────────────────

function emitModule(id, source) {
  return `__def(${JSON.stringify(id)}, function(module, exports, require) {\n${source}\n});\n`;
}

const HEADER = `#!/usr/bin/env node
// AUTO-GENERATED by cli/lhc_bundle.js — do not edit by hand.
// scscm compiler — single-file bundle (v${PKG_VERSION})
//
// Run:  node lhc.js [-i input.scscm] [-o output.sc]
//       cat input.scscm | node lhc.js > output.sc
//
// This file is self-contained: it requires only a stock Node.js >= 16.
//
'use strict';

// ── In-memory module registry ────────────────────────────────────────────────
const __MODULES = Object.create(null);
function __def(id, factory) { __MODULES[id] = { factory, exports: undefined }; }
function __req(id) {
  // Pass-through for built-ins ('node:fs', 'fs', 'path', etc.)
  if (!id.startsWith('./') && !id.startsWith('../')) return require(id);
  // Normalize relative ids to './name.js'
  const norm = id.endsWith('.js') ? id : id + '.js';
  const slot = __MODULES[norm] || __MODULES[id];
  if (!slot) throw new Error('lhc bundle: module not found: ' + id);
  if (slot.exports === undefined) {
    const mod = { exports: {} };
    slot.exports = mod.exports;
    slot.factory(mod, mod.exports, __req);
    slot.exports = mod.exports;
  }
  return slot.exports;
}

`;

// ── Build ────────────────────────────────────────────────────────────────────

function build() {
  let body = '';
  for (const rel of MODULES) {
    let src = readModule(rel);
    if (rel === './hc_utils.js') src = patchHcUtils(src);
    body += emitModule(rel, src);
  }

  // Entry: run inline in an IIFE with __req as its `require`. This way any
  // `require('./foo')` inside lhc.js routes through the registry; built-ins
  // pass through to the global require.
  let entrySrc = readModule(ENTRY);
  entrySrc = patchEntry(entrySrc);

  const FOOTER = `
// === Entry: ${ENTRY} ===
(function() {
  const require = __req;
${entrySrc}
  // Always run main() (the require.main guard was stripped at bundle time).
  main().catch(function(err) {
    console.error('scscm: ' + (err && err.message ? err.message : err));
    process.exit(1);
  });
})();
`;

  return HEADER + body + FOOTER;
}

// ── Write ────────────────────────────────────────────────────────────────────

function fileSize(bytes) {
  return bytes >= 1024 * 1024
    ? `${(bytes / (1024 * 1024)).toFixed(2)} MB`
    : `${(bytes / 1024).toFixed(1)} KB`;
}

const out = build();
fs.mkdirSync(outDir, { recursive: true });
const outPath = path.join(outDir, 'lhc.js');
fs.writeFileSync(outPath, out, 'utf8');
fs.chmodSync(outPath, 0o755);

console.log(`✓ ${outPath} (${fileSize(fs.statSync(outPath).size)}, scscm v${PKG_VERSION})`);
console.log(`  Run with: node ${outPath} [args...]`);
